<script>const cfg=<?=json_encode($config,JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const token=localStorage.getItem('admin_token')||sessionStorage.getItem('admin_token')||'';const clear=()=>{localStorage.removeItem('admin_token');sessionStorage.removeItem('admin_token');};const login=()=>location.replace(cfg.loginUrl);const esc=v=>String(v??'-').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function start(){if(!token)return login();try{const guard=await fetch(cfg.apiDashboardUrl,{headers:{Authorization:'Bearer '+token,Accept:'application/json'}});if(!guard.ok){clear();return login();}const guardData=await guard.json();const section=<?=json_encode($key)?>;if(section==='profil'){setupAdminProfile();await loadAdminProfile();return;}if(section==='fasilitas'){setupFacilities();await loadFacilities();return;}if(section==='ulasan'){setupReviews();await loadReviews();return;}if(section==='pengguna'){setupUsers();await loadUsers();return;}const res=await fetch(cfg.apiUrl,{headers:{Authorization:'Bearer '+token,Accept:'application/json'}});const json=await res.json();if(!res.ok)throw new Error(json.message||'Gagal memuat data.');const rows=Array.isArray(json.data)?json.data:(json.data?[json.data]:[]);if(section==='kategori'){const categoryPhoto=name=>{const n=String(name||'').toLocaleLowerCase('id-ID');if(n.includes('alam')||n.includes('gunung'))return '../assets/images/telaga.png?v=20261112-exact';if(n.includes('air')||n.includes('curug')||n.includes('air terjun'))return '../assets/images/kategori-air-curug.jpeg?v=20261112-exact';if(n.includes('buatan')||n.includes('kuliner'))return '../assets/images/kategori-buatan-kuliner.jpeg?v=20261112-exact';if(n.includes('sejarah')||n.includes('budaya'))return '../assets/images/kategori-sejarah-budaya.jpeg?v=20261112-exact';return '../assets/images/img.png';};document.getElementById('resourceHead').innerHTML='<tr><th>No</th><th>Foto</th><th>Kategori</th><th>Jumlah Wisata</th></tr>';document.getElementById('resourceRows').innerHTML=rows.length?rows.map((r,i)=>'<tr><td class="kategori-number" data-label="No">'+(i+1)+'</td><td class="kategori-photo" data-label="Foto"><img src="'+categoryPhoto(r.name)+'" alt="Foto '+esc(r.name)+'" loading="lazy"></td><td class="kategori-name" data-label="Kategori">'+esc(r.name)+'</td><td class="kategori-total" data-label="Jumlah wisata">'+esc(r.total_destinations??0)+'</td></tr>').join(''):'<tr><td colspan="4" class="text-center py-4">Belum ada data kategori.</td></tr>';document.getElementById('resourceMessage').textContent='Data berhasil dimuat ('+rows.length+' kategori).';}else{let cols=section==='fasilitas'?['id','name','icon_code','description']:section==='pengguna'?['id','nama','email','no_telepon']:['id_ulasan','nama_pengguna','nama_wisata','rating','komentar','tanggal_ulasan'];document.getElementById('resourceHead').innerHTML='<tr>'+cols.map(c=>'<th>'+esc(c.replaceAll('_',' '))+'</th>').join('')+'</tr>';document.getElementById('resourceRows').innerHTML=rows.length?rows.map(r=>'<tr>'+cols.map(c=>'<td>'+esc(r[c])+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+cols.length+'" class="text-center py-4">Belum ada data.</td></tr>';document.getElementById('resourceMessage').textContent='Data berhasil dimuat ('+rows.length+' data).';}}catch(e){document.getElementById('resourceMessage').textContent=e.message||'Terjadi kesalahan.';}}
const facilityModal=document.getElementById('facilityModal');
function facilityStatus(message,isError=false){const el=document.getElementById('resourceMessage');if(el){el.textContent=message;el.classList.toggle('is-error',isError);}}
async function facilityRequest(url=cfg.apiUrl,options={}){const headers={Authorization:'Bearer '+token,Accept:'application/json',...(options.headers||{})};if(options.body)headers['Content-Type']='application/json';const response=await fetch(url,{...options,headers});let payload={};try{payload=await response.json();}catch(_){payload={};}if(response.status===403){clear();login();throw new Error('Sesi admin berakhir. Silakan login kembali.');}if(!response.ok)throw new Error(payload.message||'Permintaan fasilitas gagal diproses.');return payload;}
function facilityModalOpen(item=null){const form=document.getElementById('facilityForm');form.reset();document.getElementById('facilityFormError').textContent='';document.getElementById('facilityModalTitle').textContent=item?'Edit Fasilitas':'Tambah Fasilitas';form.dataset.facilityId=item?String(item.id):'';document.getElementById('facilityName').value=item?.name||'';document.getElementById('facilityIcon').value=item?.icon_code||'';document.getElementById('facilityDescription').value=item?.description||'';if(facilityModal){facilityModal.classList.add('is-open');facilityModal.setAttribute('aria-hidden','false');document.body.classList.add('facility-modal-open');document.getElementById('facilityName').focus();}}
function facilityModalClose(){if(facilityModal){facilityModal.classList.remove('is-open');facilityModal.setAttribute('aria-hidden','true');document.body.classList.remove('facility-modal-open');}}
function setupFacilities(){const addBtn=document.getElementById('addFacilityButton');if(addBtn)addBtn.addEventListener('click',()=>facilityModalOpen());if(facilityModal){facilityModal.querySelectorAll('[data-close-facility-modal]').forEach(el=>el.addEventListener('click',facilityModalClose));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&facilityModal.classList.contains('is-open'))facilityModalClose();});}const rows=document.getElementById('resourceRows');if(rows){rows.addEventListener('click',async event=>{const button=event.target.closest('[data-facility-action]');if(!button)return;const id=button.dataset.id;try{if(button.dataset.facilityAction==='edit'){const result=await facilityRequest(cfg.apiUrl+'/'+encodeURIComponent(id));facilityModalOpen(result.data||{});}else if(button.dataset.facilityAction==='delete'){const row=facilitiesCache.find(item=>String(item.id)===String(id));if(!window.confirm('Hapus fasilitas '+(row?.name||'ini')+'?'))return;button.disabled=true;const result=await facilityRequest(cfg.apiUrl+'/'+encodeURIComponent(id),{method:'DELETE'});facilityStatus(result.message||'Fasilitas berhasil dihapus.');await loadFacilities(false);}}catch(error){facilityStatus(error.message,true);button.disabled=false;}});}const form=document.getElementById('facilityForm');if(form)form.addEventListener('submit',saveFacility);}
let facilitiesCache=[];let facilityPage=1;const facilityPageSize=5;
function facilityIconMarkup(item){const supplied=Array.isArray(item.icons)?item.icons:(Array.isArray(item.icon_codes)?item.icon_codes:(item.icon_code?[item.icon_code]:[]));const icons=supplied.flatMap(v=>String(v??'').split(/[;,|]/)).map(v=>v.trim()).filter(Boolean).slice(0,8);if(!icons.length)return '<span class="facility-icon-placeholder">—</span>';const aliases={'camera':'bi-camera-fill','kamera':'bi-camera-fill','fa-camera':'bi-camera-fill','masjid':'bi-house-fill','mushola':'bi-house-fill','toilet':'bi-gender-ambiguous','restroom':'bi-gender-ambiguous','fa-restroom':'bi-gender-ambiguous','parking':'bi-car-front-fill','parkir':'bi-car-front-fill','fa-parking':'bi-car-front-fill','wifi':'bi-wifi','internet':'bi-wifi'};return '<div class="facility-icon-list">'+icons.map(code=>{const key=code.toLocaleLowerCase('id-ID');const safe=aliases[key]||(code.match(/^(?:bi\s+)?bi-[a-z0-9-]+$/)?code.replace(/^bi\s+/,''):(/^bi-[a-z0-9-]+$/.test(code)?code:''));return safe?'<span class="facility-icon-chip" title="'+esc(code)+'"><i class="bi '+esc(safe)+'"></i></span>':'<span class="facility-icon-chip facility-icon-text" title="'+esc(code)+'">'+esc(code.slice(0,3))+'</span>';}).join('')+'</div>'; }
function renderFacilityTable(){const total=facilitiesCache.length;const pages=Math.max(1,Math.ceil(total/facilityPageSize));facilityPage=Math.min(facilityPage,pages);const start=(facilityPage-1)*facilityPageSize;const shown=facilitiesCache.slice(start,start+facilityPageSize);document.getElementById('resourceHead').innerHTML='<tr><th>No</th><th>Ikon</th><th>Nama Fasilitas</th><th>Keterangan</th><th>Aksi</th></tr>';document.getElementById('resourceRows').innerHTML=shown.length?shown.map((item,index)=>{const name=item.facility_name||item.nama_fasilitas||item.name||'-';const description=item.description||item.keterangan||'-';return '<tr><td data-label="No" class="facility-number">'+(start+index+1)+'</td><td data-label="Ikon" class="facility-icons-cell">'+facilityIconMarkup(item)+'</td><td data-label="Nama Fasilitas" class="facility-name">'+esc(name)+'</td><td data-label="Keterangan" class="facility-description">'+esc(description)+'</td><td data-label="Aksi" class="facility-actions"><button type="button" class="facility-action-button is-edit" data-facility-action="edit" data-id="'+esc(item.id)+'" aria-label="Edit '+esc(name)+'"><i class="bi bi-pencil-square"></i></button><button type="button" class="facility-action-button is-delete" data-facility-action="delete" data-id="'+esc(item.id)+'" aria-label="Hapus '+esc(name)+'"><i class="bi bi-trash-fill"></i></button></td></tr>';}).join(''):'<tr><td colspan="5" class="facility-empty">Belum ada data fasilitas. Klik Tambah Fasilitas untuk membuat data pertama.</td></tr>';const rangeEl=document.getElementById('facilityRange');if(rangeEl)rangeEl.textContent=total?'Menampilkan '+(start+1)+'-'+Math.min(start+facilityPageSize,total)+' dari '+total+' data fasilitas':'Menampilkan 0-0 dari 0 data fasilitas';const nav=document.getElementById('facilityPagination');if(nav){nav.innerHTML='';if(pages>1){const make=(label,page,disabled=false,active=false)=>{const b=document.createElement('button');b.type='button';b.className='facility-page-button'+(active?' is-active':'');b.innerHTML=label;b.disabled=disabled;b.setAttribute('aria-label',typeof label==='string'?label:'Halaman '+page);b.addEventListener('click',()=>{facilityPage=page;renderFacilityTable();});nav.appendChild(b);};make('<i class="bi bi-chevron-left"></i>',Math.max(1,facilityPage-1),facilityPage===1);for(let p=1;p<=pages;p++){if(pages>5&&p>2&&p<pages-1&&Math.abs(p-facilityPage)>1){if(p===3||p===pages-2){const dots=document.createElement('span');dots.className='facility-page-dots';dots.textContent='...';nav.appendChild(dots);}continue;}make(String(p),p,false,p===facilityPage);}make('<i class="bi bi-chevron-right"></i>',Math.min(pages,facilityPage+1),facilityPage===pages);}}}
async function loadFacilities(showLoading=true){if(showLoading)facilityStatus('Memuat data fasilitas...');try{const result=await facilityRequest();facilitiesCache=Array.isArray(result.data)?result.data:[];facilityPage=1;renderFacilityTable();facilityStatus('Data berhasil dimuat ('+facilitiesCache.length+' fasilitas).');}catch(error){facilityStatus(error.message,true);document.getElementById('resourceHead').innerHTML='';document.getElementById('resourceRows').innerHTML='<tr><td colspan="5" class="facility-empty">Data fasilitas gagal dimuat. Periksa koneksi API dan migrasi database.</td></tr>';const rangeEl=document.getElementById('facilityRange');if(rangeEl)rangeEl.textContent='';const nav=document.getElementById('facilityPagination');if(nav)nav.innerHTML='';}}
async function saveFacility(event){event.preventDefault();const form=event.currentTarget;const id=form.dataset.facilityId;const payload={name:document.getElementById('facilityName').value.trim(),icon_code:document.getElementById('facilityIcon').value.trim(),description:document.getElementById('facilityDescription').value.trim()};const errorBox=document.getElementById('facilityFormError');const saveButton=document.getElementById('saveFacilityButton');errorBox.textContent='';if(!payload.name){errorBox.textContent='Nama fasilitas wajib diisi.';return;}saveButton.disabled=true;saveButton.textContent='Menyimpan...';try{const result=await facilityRequest(id?cfg.apiUrl+'/'+encodeURIComponent(id):cfg.apiUrl,{method:id?'PUT':'POST',body:JSON.stringify(payload)});facilityModalClose();facilityStatus(result.message||'Data fasilitas berhasil disimpan.');await loadFacilities(false);}catch(error){errorBox.textContent=error.message;}finally{saveButton.disabled=false;saveButton.textContent='Simpan';}}
let reviewAll=[],reviewFiltered=[],reviewPage=1,reviewPageSize=5,reviewPendingId=null;
function reviewStatus(text,error=false){const el=document.getElementById('reviewNotice');if(el){el.textContent=text;el.classList.toggle('is-error',error);}}
async function reviewRequest(url=cfg.apiUrl,options={}){const response=await fetch(url,{...options,headers:{Authorization:'Bearer '+token,Accept:'application/json',...(options.headers||{})}});let payload={};try{payload=await response.json();}catch(_){payload={};}if(response.status===403){clear();login();throw new Error('Sesi admin berakhir. Silakan login kembali.');}if(!response.ok)throw new Error(payload.message||'Permintaan ulasan gagal diproses.');return payload;}
function reviewDate(value){if(!value)return '-';const d=new Date(String(value).replace(' ','T'));return Number.isNaN(d.getTime())?String(value):new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d);}
function reviewShowModal(id,show){const el=document.getElementById(id);el.classList.toggle('is-open',show);el.setAttribute('aria-hidden',show?'false':'true');document.body.classList.toggle('review-modal-open',document.querySelector('.review-modal.is-open')!==null);}
function reviewResult(success,message){const icon=document.getElementById('reviewResultIcon');icon.className='review-result-icon '+(success?'is-success':'is-error');icon.innerHTML=success?'<i class="bi bi-trash-fill"></i>':'<i class="bi bi-x-lg"></i>';document.getElementById('reviewResultTitle').textContent=success?'Berhasil di Hapus!':'Gagal di Hapus !';document.getElementById('reviewResultText').textContent=message;reviewShowModal('reviewResultModal',true);}
function renderReviewTable(){const tbody=document.getElementById('reviewRows'),empty=document.getElementById('reviewEmpty'),total=reviewFiltered.length,pages=Math.max(1,Math.ceil(total/reviewPageSize));reviewPage=Math.min(reviewPage,pages);const start=(reviewPage-1)*reviewPageSize,shown=reviewFiltered.slice(start,start+reviewPageSize);tbody.innerHTML=shown.map((r,i)=>'<tr><td data-label="No">'+(start+i+1)+'</td><td data-label="Nama pengguna">'+esc(r.nama_pengguna||r.nama_user||'-')+'</td><td data-label="Wisata">'+esc(r.nama_wisata||r.destination_name||'-')+'</td><td data-label="Rating"><span class="review-stars" aria-label="Rating '+Number(r.rating||0)+' dari 5">'+Array.from({length:5},(_,n)=>'<i class="bi '+(n<Math.round(Number(r.rating)||0)?'bi-star-fill':'bi-star')+'"></i>').join('')+'</span></td><td data-label="Komentar">'+esc(r.komentar||'-')+'</td><td data-label="Tanggal">'+esc(reviewDate(r.tanggal_ulasan))+'</td><td data-label="Aksi"><button type="button" class="review-delete-button" data-review-delete="'+esc(r.id_ulasan)+'" aria-label="Hapus ulasan"><i class="bi bi-trash-fill"></i></button></td></tr>').join('');
const noData=total===0;empty.hidden=!noData;tbody.closest('table').style.display='';if(noData){const hasSearch=document.getElementById('reviewSearch').value.trim()||document.getElementById('reviewRating').value;empty.innerHTML=hasSearch?'<div class="review-empty-icon is-search"><i class="bi bi-chat-square-x"></i></div><h2>Ulasan tidak di temukan</h2><p>Ulasan yang anda cari tidak di temukan</p>':'<div class="review-empty-icon"><i class="bi bi-chat-square-x"></i></div><h2>Belum ada ulasan dari pengguna</h2><p>Saat ini belum ada ulasan dari pengguna<br>di website Explore MajaKu</p>';}
document.getElementById('reviewRange').textContent=total?'Menampilkan '+(start+1)+'-'+Math.min(start+reviewPageSize,total)+' dari '+total+' data ulasan':'Menampilkan 0-0 dari 0 data ulasan';const nav=document.getElementById('reviewPagination');nav.innerHTML='';if(pages>1){const add=(label,page,disabled=false,active=false)=>{const b=document.createElement('button');b.type='button';b.className='review-page-button'+(active?' is-active':'');b.innerHTML=label;b.disabled=disabled;b.addEventListener('click',()=>{reviewPage=page;renderReviewTable();});nav.appendChild(b);};add('<i class="bi bi-chevron-left"></i>',Math.max(1,reviewPage-1),reviewPage===1);for(let n=1;n<=pages;n++){if(pages>5&&n>2&&n<pages-1&&Math.abs(n-reviewPage)>1){if(n===3||n===pages-2){const dots=document.createElement('span');dots.textContent='...';nav.appendChild(dots);}continue;}add(String(n),n,false,n===reviewPage);}add('<i class="bi bi-chevron-right"></i>',Math.min(pages,reviewPage+1),reviewPage===pages);}}
function filterReviews(){const q=document.getElementById('reviewSearch').value.trim().toLocaleLowerCase('id-ID'),rating=document.getElementById('reviewRating').value;reviewFiltered=reviewAll.filter(r=>{const hay=[r.nama_pengguna,r.nama_user,r.nama_wisata,r.komentar].join(' ').toLocaleLowerCase('id-ID');return (!q||hay.includes(q))&&(!rating||Math.round(Number(r.rating))===Number(rating));});reviewPage=1;reviewStatus(q||rating?(reviewFiltered.length?'':'Ulasan yang anda cari tidak di temukan'):'');renderReviewTable();}
async function loadReviews(){reviewStatus('');document.getElementById('reviewRows').innerHTML='<tr><td colspan="7" class="review-loading">Memuat data ulasan...</td></tr>';try{const result=await reviewRequest();reviewAll=Array.isArray(result.data)?result.data:[];filterReviews();if(reviewAll.length)reviewStatus('');}catch(error){document.getElementById('reviewRows').innerHTML='';document.querySelector('.review-table').style.display='';document.getElementById('reviewEmpty').hidden=false;document.getElementById('reviewEmpty').innerHTML='<div class="review-empty-icon is-error"><i class="bi bi-x-lg"></i></div><h2 class="is-error-text">Gagal memuat data ulasan</h2><p>Maaf, Data ulasan gagal di muat.<br>silahkan coba kembali.</p><button type="button" class="review-retry-button" id="reviewRetry">Coba lagi</button>';document.getElementById('reviewRetry').onclick=loadReviews;document.getElementById('reviewRange').textContent='';document.getElementById('reviewPagination').innerHTML='';}}
function setupReviews(){document.getElementById('reviewSearchButton').addEventListener('click',filterReviews);document.getElementById('reviewSearch').addEventListener('keydown',e=>{if(e.key==='Enter')filterReviews();});document.getElementById('reviewRating').addEventListener('change',filterReviews);document.getElementById('reviewRows').addEventListener('click',e=>{const b=e.target.closest('[data-review-delete]');if(!b)return;const row=reviewAll.find(r=>String(r.id_ulasan)===String(b.dataset.reviewDelete));if(!row)return;reviewPendingId=row.id_ulasan;document.getElementById('reviewDeleteName').textContent=row.nama_pengguna||row.nama_user||'pengguna';reviewShowModal('reviewConfirmModal',true);});document.querySelectorAll('[data-review-close]').forEach(b=>b.addEventListener('click',()=>reviewShowModal('reviewConfirmModal',false)));document.getElementById('reviewConfirmDelete').addEventListener('click',async()=>{if(!reviewPendingId)return;const button=document.getElementById('reviewConfirmDelete');button.disabled=true;button.textContent='Menghapus...';try{const result=await reviewRequest(cfg.apiUrl+'/'+encodeURIComponent(reviewPendingId),{method:'DELETE'});reviewShowModal('reviewConfirmModal',false);reviewPendingId=null;await loadReviews();reviewResult(true,result.message||'Ulasan dari pengguna tersebut telah di hapus dari data ulasan');}catch(error){reviewShowModal('reviewConfirmModal',false);reviewResult(false,'Ulasan dari pengguna tersebut gagal di hapus dari data ulasan');}finally{button.disabled=false;button.textContent='Ya, Hapus Ulasan';}});document.getElementById('reviewResultOk').addEventListener('click',()=>reviewShowModal('reviewResultModal',false));document.querySelector('[data-review-result-close]').addEventListener('click',()=>reviewShowModal('reviewResultModal',false));document.addEventListener('keydown',e=>{if(e.key==='Escape'){reviewShowModal('reviewConfirmModal',false);reviewShowModal('reviewResultModal',false);}});}

let userPage=1,userQuery='',userTotal=0,userTotalUsers=0,userTotalPages=0,userRequestSequence=0;
const userPageSize=5;
function userNotice(message='',error=false){const el=document.getElementById('userNotice');if(!el)return;el.textContent=message;el.classList.toggle('is-error',error);}
function userDate(value){if(!value)return '-';const raw=String(value).trim();const match=raw.match(/^(\d{1,2})\s+([A-Za-zÀ-ÿ]+)\s+(\d{4})$/);if(match)return match[1]+'/'+({'Jan':'01','Feb':'02','Mar':'03','Apr':'04','Mei':'05','May':'05','Jun':'06','Jul':'07','Agu':'08','Aug':'08','Sep':'09','Okt':'10','Oct':'10','Nov':'11','Des':'12','Dec':'12'}[match[2]]||match[2])+'/'+match[3];const d=new Date(raw.replace(' ','T'));return Number.isNaN(d.getTime())?raw:new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d);}
async function userRequest(page=1,search=''){const url=new URL(cfg.apiUrl,window.location.href);url.searchParams.set('page',String(page));url.searchParams.set('limit',String(userPageSize));if(search)url.searchParams.set('search',search);const response=await fetch(url.toString(),{headers:{Authorization:'Bearer '+token,Accept:'application/json'},cache:'no-store'});let payload={};try{payload=await response.json();}catch(_){payload={};}if(response.status===403){clear();login();throw new Error('Sesi admin berakhir. Silakan login kembali.');}if(!response.ok){const error=new Error(payload.message||'Gagal memuat daftar pengguna.');error.status=response.status;error.apiStatus=payload.status;throw error;}return payload;}
function userRenderPagination(){const nav=document.getElementById('userPagination');nav.innerHTML='';if(userTotalPages<=1)return;const add=(label,page,disabled=false,active=false,aria='')=>{const b=document.createElement('button');b.type='button';b.className='user-page-button'+(active?' is-active':'');b.disabled=disabled;b.innerHTML=label;b.setAttribute('aria-label',aria||('Halaman '+page));b.addEventListener('click',()=>loadUsers(page,userQuery));nav.appendChild(b);};add('<i class="bi bi-chevron-left"></i>',Math.max(1,userPage-1),userPage===1,false,'Halaman sebelumnya');let pages=[];if(userTotalPages<=5){for(let n=1;n<=userTotalPages;n++)pages.push(n);}else{pages=[1];if(userPage>3)pages.push('...');for(let n=Math.max(2,userPage-1);n<=Math.min(userTotalPages-1,userPage+1);n++)pages.push(n);if(userPage<userTotalPages-2)pages.push('...');pages.push(userTotalPages);}let last='';pages.forEach(n=>{if(n==='...'){if(last!=='...'){const dots=document.createElement('span');dots.className='user-page-dots';dots.textContent='...';nav.appendChild(dots);}last=n;return;}add(String(n),n,false,n===userPage);last=n;});add('<i class="bi bi-chevron-right"></i>',Math.min(userTotalPages,userPage+1),userPage===userTotalPages,false,'Halaman berikutnya');}
function userShowError(server=false){const table=document.querySelector('.user-table'),state=document.getElementById('userErrorState');table.style.display='none';state.hidden=false;document.getElementById('userErrorTitle').textContent=server?'Terjadi kesalahan pada server':'Gagal Memuat data pengguna';document.getElementById('userErrorText').innerHTML=server?'Maaf, server sedang bermasalah. silahkan<br>coba beberapa saat lagi.':'Maaf, Data pengguna gagal di muat.<br>silahkan coba kembali.';document.getElementById('userRange').textContent='';document.getElementById('userTotalSummary').textContent='Total pengguna: —';document.getElementById('userPagination').innerHTML='';userNotice('');}
async function loadUsers(page=1,search=userQuery){
 const requestId=++userRequestSequence;
 const table=document.querySelector('.user-table'),state=document.getElementById('userErrorState'),tbody=document.getElementById('userRows');
 state.hidden=true;table.style.display='table';tbody.innerHTML='<tr><td colspan="4" class="user-loading">Memuat data pengguna...</td></tr>';userNotice('');
 try{
  const result=await userRequest(page,search);
  if(requestId!==userRequestSequence)return;
  const data=Array.isArray(result.data)?result.data:[],pg=result.pagination||{};
  userPage=Number(pg.current_page)||page;userTotal=Number(pg.total_data??result.total_data)||0;
  userTotalUsers=Number(result.total_users??result.totalUsers??userTotal)||0;
  userTotalPages=Number(pg.total_pages??result.total_pages)||0;userQuery=search;
  tbody.innerHTML=data.length?data.map((r,i)=>'<tr><td data-label="No">'+((userPage-1)*userPageSize+i+1)+'</td><td data-label="Nama">'+esc(r.nama||'-')+'</td><td data-label="Email">'+esc(r.email||r.no_telepon||'-')+'</td><td data-label="Tanggal Daftar">'+esc(userDate(r.created_at))+'</td></tr>').join(''):'<tr><td colspan="4" class="user-no-data">Tidak ada data pengguna.</td></tr>';
  const first=userTotal?((userPage-1)*userPageSize+1):0,last=Math.min(userPage*userPageSize,userTotal);
  document.getElementById('userRange').textContent='Menampilkan '+first+'-'+last+' dari '+userTotal+' hasil'+(search?' pencarian':'');
  document.getElementById('userTotalSummary').textContent='Total pengguna: '+userTotalUsers;
  userRenderPagination();
  if(search&&userTotal===0)userNotice('Pengguna dengan nama atau email tersebut tidak ditemukan.',true);
 }catch(error){
  if(requestId!==userRequestSequence)return;
  if(error.status>=500||error.apiStatus==='server_error')userShowError(true);else userShowError(false);
 }
}
function setupUsers(){const input=document.getElementById('userSearch'),button=document.getElementById('userSearchButton');const search=()=>{const raw=input.value.trim();if(raw.length>100){userNotice('Kata pencarian maksimal 100 karakter.',true);input.focus();return;}if(/[\u0000-\u001F\u007F]/.test(raw)){userNotice('Kata pencarian mengandung karakter yang tidak valid.',true);input.focus();return;}loadUsers(1,raw);};button.addEventListener('click',search);input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();search();}});input.addEventListener('input',()=>{if(input.value.length<=100)userNotice('');});document.getElementById('userRetryButton').addEventListener('click',()=>loadUsers(userPage,userQuery));}

async function adminProfileRequest(url,options={}){const headers={Authorization:'Bearer '+token,Accept:'application/json',...(options.headers||{})};if(options.body)headers['Content-Type']='application/json';const response=await fetch(url,{...options,headers,cache:'no-store'});let payload={};try{payload=await response.json();}catch(_){payload={};}if(response.status===403){clear();login();throw new Error('Sesi admin berakhir. Silakan login kembali.');}if(!response.ok){const error=new Error(payload.message||'Permintaan gagal diproses.');error.status=response.status;throw error;}return payload;}
function profileToast(message,error=false){const el=document.getElementById('adminProfileToast');if(!el)return;el.textContent=message;el.classList.toggle('is-error',error);el.classList.add('is-visible');window.clearTimeout(profileToast.timer);profileToast.timer=window.setTimeout(()=>el.classList.remove('is-visible'),3500);}
let adminProfileData={};
async function loadAdminProfile(){try{const result=await adminProfileRequest(cfg.apiDashboardUrl.replace(/\/dashboard$/,'/profile'));adminProfileData=result.data||{};const name=adminProfileData.name||'Administrator MajaKu';document.getElementById('profileTopName').textContent='Admin 1';document.getElementById('profileDisplayName').innerHTML=esc(name);document.getElementById('profileName').textContent=name;document.getElementById('profileUsername').textContent=adminProfileData.username||'-';document.getElementById('profileEmail').textContent=adminProfileData.email||'-';}catch(error){profileToast(error.message||'Profil admin gagal dimuat.',true);document.getElementById('profileName').textContent='Gagal memuat profil';}}
function profileModal(open){const modal=document.getElementById('adminProfileModal');modal.classList.toggle('is-open',open);modal.setAttribute('aria-hidden',String(!open));if(open){document.getElementById('editAdminName').value=adminProfileData.name||'';document.getElementById('editAdminNameError').textContent='';document.getElementById('editAdminName').focus();}}
function setPasswordError(id,message){document.getElementById(id).textContent=message;}
function setupAdminProfile(){document.getElementById('editAdminProfile').addEventListener('click',()=>profileModal(true));document.querySelectorAll('[data-close-profile]').forEach(el=>el.addEventListener('click',()=>profileModal(false)));document.addEventListener('keydown',e=>{if(e.key==='Escape')profileModal(false);});document.querySelectorAll('[data-toggle-password]').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.togglePassword);const visible=input.type==='password';input.type=visible?'text':'password';button.innerHTML='<i class="bi '+(visible?'bi-eye-slash-fill':'bi-eye-fill')+'"></i>';button.setAttribute('aria-label',visible?'Sembunyikan password':'Tampilkan password');}));['currentAdminPassword','newAdminPassword','confirmAdminPassword'].forEach(id=>document.getElementById(id).addEventListener('input',()=>{const map={currentAdminPassword:'currentPasswordError',newAdminPassword:'newPasswordError',confirmAdminPassword:'confirmPasswordError'};setPasswordError(map[id],'');}));document.getElementById('adminPasswordForm').addEventListener('submit',submitAdminPassword);document.getElementById('adminProfileForm').addEventListener('submit',saveAdminProfile);}
async function saveAdminProfile(event){event.preventDefault();const name=document.getElementById('editAdminName').value.trim();const error=document.getElementById('editAdminNameError');error.textContent='';if(!name){error.textContent='Nama lengkap wajib diisi.';return;}if(name.length>255){error.textContent='Nama maksimal 255 karakter.';return;}const button=document.getElementById('saveAdminProfile');button.disabled=true;button.textContent='Menyimpan...';try{const result=await adminProfileRequest(cfg.apiDashboardUrl.replace(/\/dashboard$/,'/profile'),{method:'PUT',body:JSON.stringify({name})});adminProfileData={...adminProfileData,...(result.data||{}),name};document.getElementById('profileDisplayName').textContent=name;document.getElementById('profileName').textContent=name;profileModal(false);profileToast(result.message||'Profil admin berhasil diperbarui.');}catch(err){error.textContent=err.message||'Profil gagal diperbarui.';}finally{button.disabled=false;button.textContent='Simpan Perubahan';}}
async function submitAdminPassword(event){event.preventDefault();const current=document.getElementById('currentAdminPassword').value;const next=document.getElementById('newAdminPassword').value;const confirm=document.getElementById('confirmAdminPassword').value;let valid=true;setPasswordError('currentPasswordError','');setPasswordError('newPasswordError','');setPasswordError('confirmPasswordError','');if(!current){setPasswordError('currentPasswordError','Password saat ini wajib di isi');valid=false;}if(!next){setPasswordError('newPasswordError','Password baru wajib di isi');valid=false;}else if(next.length<8){setPasswordError('newPasswordError','Password minimal 8 karakter');valid=false;}else if(next.length>72){setPasswordError('newPasswordError','Password maksimal 72 byte');valid=false;}else if(!/[a-z]/.test(next)||!/[A-Z]/.test(next)||!/[0-9]/.test(next)||!/[^A-Za-z0-9]/.test(next)){setPasswordError('newPasswordError','Gunakan huruf besar, huruf kecil, angka, dan karakter khusus.');valid=false;}else if(next===current){setPasswordError('newPasswordError','Password baru tidak boleh sama dengan password sebelumnya');valid=false;}if(!confirm){setPasswordError('confirmPasswordError','Konfirmasi password baru wajib di isi');valid=false;}else if(confirm!==next){setPasswordError('confirmPasswordError','Konfirmasi password tidak sesuai dengan password baru');valid=false;}if(!valid)return;const button=document.getElementById('adminPasswordSubmit');button.disabled=true;button.innerHTML='<i class="bi bi-arrow-repeat"></i> Memproses...';try{const result=await adminProfileRequest(cfg.apiDashboardUrl.replace(/\/dashboard$/,'/change-password'),{method:'PUT',body:JSON.stringify({current_password:current,new_password:next})});document.getElementById('adminPasswordForm').reset();profileToast(result.message||'Password berhasil diperbarui. Silakan login kembali.');window.setTimeout(()=>{clear();login();},1400);}catch(error){if(error.status===400||/kata sandi saat ini/i.test(error.message)){setPasswordError('currentPasswordError','Password lama tidak cocok');}else if(error.status===422){setPasswordError('newPasswordError',error.message);}else{profileToast(error.message||'Password gagal diperbarui.',true);}}finally{button.disabled=false;button.innerHTML='<i class="bi bi-lock"></i> Perbarui password';}}

async function logout(){try{await fetch(cfg.apiLogoutUrl,{method:'POST',headers:{Authorization:'Bearer '+token}});}finally{clear();login();}}document.getElementById('logoutButton').onclick=logout;document.getElementById('mobileLogoutButton').onclick=logout;document.getElementById('sidebarCollapse').onclick=()=>document.body.classList.toggle('sidebar-collapsed');document.getElementById('mobileMenuButton').onclick=()=>document.body.classList.toggle('mobile-sidebar-open');document.getElementById('sidebarBackdrop').onclick=()=>document.body.classList.remove('mobile-sidebar-open');start();</script></body></html>
